async function filesUnder(directory){
  const absoluteDirectory=resolve(projectRoot,directory),entries=await readdir(absoluteDirectory,{withFileTypes:true});
  const nested=await Promise.all(entries.map(async e=>{
    const path=relative(projectRoot,resolve(absoluteDirectory,e.name)).replaceAll('\\','/');
    return e.isDirectory()?filesUnder(path):[path];
  }));
  return nested.flat();
}
